# -*- coding: utf-8 -*-
TITLE = 'TIỆM ĂN THÔNG THIÊN GIÚP PHẾ THÁI TỬ ĐOẠT LẠI NGAI VÀNG'

INTRO_DUB = [
    ('blk1', '01:19:23.00', 0.0, 0.25, 'Phụ hoàng, nhi thần được trời ban thần thuật,'),
    ('blk1', '01:19:23.00', 0.0, 0.35, 'có thể phân biệt kịch độc, xin cho nhi thần thử rượu.'),
    ('blk1', '01:19:23.00', 0.0, 0.3, 'Chén rượu quế hoa này có độc,'),
    ('blk1', '01:19:23.00', 0.0, 0.45, 'làm càn, Thái tử dám mang yêu vật vu hãm bổn cung.'),
    ('blk2', '01:19:58.00', 0.0, 0.28, 'Bệ hạ, năm nghìn tư binh đã phá cổng Huyền Vũ,'),
    ('blk2', '01:19:58.00', 0.0, 0.35, 'đang ồ ạt đánh thẳng vào đại điện.'),
    ('blk2', '01:19:58.00', 0.0, 0.45, 'Phụ hoàng đã trúng độc, hoàng huynh còn không mau chịu trói.'),
    ('blk3', '01:20:24.50', 1.25, 0.3, 'Thiết giáp chiến xa giáng thế,'),
    ('blk3', '01:20:24.50', 0.0, 0.45, 'nhà họ Thôi, bổn cung đã đợi ngày này quá lâu rồi.'),
    ('blk5', '01:22:18.00', 0.0, 0.32, 'Dực nhi, trận này con thắng rồi.'),
    ('blk5', '01:22:18.00', 0.0, 0.28, 'Nhi thần không cần chém công thần,'),
    ('blk5', '01:22:18.00', 0.0, 0.35, 'nhi thần chỉ đòi lại một lẽ công đạo cho mẫu hậu,'),
    ('blk5', '01:22:18.00', 0.0, 0.25, 'và năm mươi sáu mạng người vô tội ở lãnh cung.'),
]

BEATS = [
    ('1:20:15-1:20:40,1:22:08-1:22:35', 'Giữa đại điện ngập tràn khói lửa khi năm nghìn phản quân phá cổng Huyền Vũ, Thái tử Tiêu Cảnh Dực bất ngờ lái chiến xa bọc thép lao thẳng ra sân, nghiền nát toàn bộ đội hình tinh nhuệ của nhà họ Thôi, buộc Hoàng đế phải xử trảm Thôi Trạch và đày Nhị hoàng tử ra biên ải.'),
    ('0:06:10-0:06:35,1:18:35-1:19:05', 'Cả triều đình Đại Ninh lẫn bè lũ gian thần đều không hề hay biết rằng, vị Phế Thái tử bị giam cầm ba năm nơi lãnh cung lạnh lẽo kia, thực chất lại được cô chủ quán ăn Tô Tiểu Mãn âm thầm tiếp tế, nhờ chiếc tủ lạnh hiện đại kết nối xuyên qua một nghìn năm lịch sử.'),
    ('0:00:00-0:00:50', 'Quay ngược lại thời điểm mở đầu cho mối nhân duyên vượt thời không kỳ diệu ấy, Tiêu Cảnh Dực đã nhịn đói suốt ba ngày trong Hàn Ngô Viện đến mức kiệt sức, mặc cho lão nô Phúc thúc và thiếu niên A Viên khóc lóc ngoài cửa sắt, van xin đám lính canh ban cho một ngụm nước sạch.'),
    ('0:00:50-0:01:40', 'Trong lúc đám lính canh tàn nhẫn hắt nước đuổi người tại lãnh cung ngàn năm trước, ở thế giới hiện đại cô chủ Tô Tiểu Mãn cũng đang lo lắng tính sổ nợ, bởi gã giang hồ Hồ Bưu đang ráo riết đòi năm trăm tám mươi vạn tệ, đúng lúc tivi đưa tin khai quật ngôi mộ của Tiêu Cảnh Dực.'),
    ('0:01:40-0:02:30', 'Bước qua luồng sáng kỳ ảo trên bức bình phong để lọt vào căn bếp hiện đại, Tiêu Cảnh Dực đói lả vội bốc thức ăn trên bàn khiến cô chủ nhỏ giật mình, tưởng anh là diễn viên quần chúng lẻn vào quán ăn trộm, song khi thấy anh móc ra mấy đồng tiền cổ thì cô lại mềm lòng.'),
    ('0:02:30-0:03:20', 'Nghe chàng trai có sắc mặt trắng bệch tự xưng là Phế Thái tử triều Đại Ninh, Tô Tiểu Mãn chỉ bật cười coi đó là lời nói đùa của kẻ nhập vai, rồi cô hào phóng nấu cho anh một bát mì bò hầm nóng hổi, khiến người chịu đói suốt ba năm xúc động thề sẽ khắc cốt ghi tâm.'),
    ('0:03:20-0:04:10', 'Nhìn bát mì cạn sạch cùng thần thái quý khí chẳng giống kẻ lừa đảo của anh, Tô Tiểu Mãn vội mở điện thoại tra cứu lịch sử về triều đại Đại Ninh, bàng hoàng phát hiện Phế Thái tử qua đời lúc mới hai mươi tám tuổi, nên cô liền lên sóng nhờ chuyên gia Hạ lão sư thẩm định tiền.'),
    ('0:04:10-0:05:00', 'Qua ống kính máy quay trực tiếp trên mạng, vị chuyên gia cổ vật Hạ lão sư sững sờ xác nhận đây là đồng Kiến Nguyên Thông Bảo, ông định giá mỗi đồng tiền cổ hiếm có này lên tới hai mươi vạn tệ, đồng thời hẹn cô ngày mai mang tới tiệm giao dịch khiến Tô Tiểu Mãn mừng rỡ.'),
    ('0:05:00-0:05:50', 'Quay lại phòng bếp khi Tiêu Cảnh Dực đã ăn hết ba thùng mì gói trên bàn, Tô Tiểu Mãn liền chất đầy bún ốc cùng năm mươi cây xúc xích và gà quay, hào sảng đề nghị cho anh mua chịu để đổi lấy cổ vật lâu dài, giúp hai bên cùng hợp tác làm ăn vượt qua cơn bĩ cực.'),
    ('0:05:55-0:07:30', 'Dù ban đầu mọi người đều bịt mũi e ngại trước mùi măng chua của món bún ốc, song khi nếm thử ngụm nước súp nóng hổi đầu tiên sau ba năm chịu đói rét, cả lãnh cung liền tranh nhau ăn tới mức giẫm lên chân nhau, rồi hôm sau Tiêu Cảnh Dực lại chỉnh tề sang tiệm ăn tạ ơn.'),
    ('0:07:30-0:08:25', 'Trở lại tiệm ăn với diện mạo tuấn tú sau khi giúp cô chủ nhỏ kiếm bộn tiền, Tiêu Cảnh Dực được Tô Tiểu Mãn giới thiệu món lẩu tự sôi vô cùng kỳ diệu, chỉ cần đổ nước lạnh là bốc khói làm anh ngỡ đó là tiên thuật, rồi anh xúc động kể chuyện cứu sống năm mươi sáu người.'),
    ('0:08:25-0:09:15', 'Lo lắng mùa đông khắc nghiệt sắp tới sẽ cướp đi mạng sống của người già trẻ nhỏ, Tiêu Cảnh Dực thành khẩn tháo chiếc vòng ngọc chạm hình phượng của mẫu hậu quá cố, giao cho Tô Tiểu Mãn làm vật thế chấp để đặt mua lương thực, và được cô hứa sẽ sắm chăn bông cùng áo phao lông vũ.'),
    ('0:09:15-0:10:05', 'Sau khi nhờ cô tìm vũ khí phòng thân và nói mình sắp tròn hai mươi tám tuổi, câu nói ấy khiến Tô Tiểu Mãn giật mình nhớ tới kết cục trong sử sách, trong khi ở Hàn Ngô Viện bé A Viên cùng mọi người đang ăn lẩu nóng, đồng loạt quỳ lạy cảm tạ vị thần tiên nương nương tốt bụng.'),
    ('0:10:20-0:11:15', 'Đúng lúc người trong viện đang ăn lẩu thì thái giám Lưu công công đạp cửa xông vào, hắn hung hãn đá văng những chiếc hộp trắng trên sân để tra khảo mùi thịt, mặc cho Tiêu Cảnh Dực đứng ra che chở cho những người hầu già yếu, gã thái giám vẫn cắt nửa phần cơm cùng than sưởi mùa đông.'),
    ('0:11:45-0:12:35', 'Xót xa nhìn lão nô Phúc thúc ngoài bảy mươi tuổi và bé A Viên sắp chết cóng, Tiêu Cảnh Dực vội bước qua tủ lạnh báo tin Hoàng hậu đã cắt sạch củi gạo, bởi Hàn Ngô Viện nằm ở cực Bắc lại sắp đón trận đại tuyết, khiến năm mươi sáu mạng người khó lòng cầm cự nổi qua ba ngày.'),
    ('0:12:35-0:13:25', 'Chẳng chút chần chừ trước tình thế ngàn cân treo sợi tóc của những người vô tội, Tô Tiểu Mãn lập tức ghi đơn năm mươi chăn bông cùng bốn mươi chiếc áo phao, cộng thêm hai mươi lò sưởi di động và ba trăm hộp cơm tự sôi, rồi dặn anh về chèn chặt cửa sổ chờ cô đi gom hàng.'),
    ('0:13:25-0:14:15', 'Phóng xe thẳng tới kho hậu cần trong đêm và chuyển trước mười lăm vạn tệ tiền cọc, Tô Tiểu Mãn trả gấp đôi tiền công để công nhân của Trương ca bốc vác hàng, từ chăn bông quân dụng cho tới hai trăm cân than không khói, đồng thời cô chi đậm mua đứt lô vũ khí phòng thân hạng nặng.'),
    ('0:14:15-0:15:05', 'Nhờ số lương thực chuyển sang kịp thời để mở tiệc mừng thọ tuổi hai mươi tám, cả Hàn Ngô Viện lần đầu được ăn bữa lẩu ngon hơn cả sơn hào hải vị, thế mà niềm vui chưa tàn thì A Viên đã hốt hoảng chạy vào báo tin, rằng Lưu công công đang dẫn cấm quân bưng rượu độc tới viện.'),
    ('0:15:10-0:16:00', 'Nghe tin cấm quân đã vây kín cổng viện theo ý chỉ của Hoàng hậu để bức tử, lão nô Phúc thúc cùng mọi người đồng loạt thề lấy xác già chắn trước cửa, quyết bảo vệ vị Thái tử nhân từ từng cưu mang họ suốt ba năm, còn Tiêu Cảnh Dực vội bước qua bình phong để lại thư cầu cứu.'),
    ('0:16:05-0:16:55', 'Vừa kiểm hàng xong trở về tiệm và nhìn thấy dòng chữ cầu cứu khẩn cấp trên bàn, Tô Tiểu Mãn liền vay nóng mười tám vạn tệ trên điện thoại để thuê xe, giục công nhân mang gấp hòm vũ khí phòng thân tới tiệm ăn ngay lập tức, trong khi tại Hàn Ngô Viện gã Lưu công công đang đọc chỉ.'),
    ('0:17:10-0:18:00', 'Giữa lúc Tô Tiểu Mãn treo thưởng gấp mười lần tiền công để khiêng hòm gỗ vào bếp, Tiêu Cảnh Dực cầm chén rượu độc nghẹn ngào cầu xin Lưu công công một ân huệ, mong gã thái giám sau khi anh chết hãy tha cho năm mươi sáu người, bởi họ vốn chỉ là đám người già yếu cùng trẻ nhỏ.'),
    ('0:18:05-0:18:55', 'Ngoài miệng giả vờ hứa hẹn sẽ bẩm báo Hoàng hậu tha mạng cho đám người hầu kia, song âm mưu phóng hỏa đốt sạch Hàn Ngô Viện đã bị A Viên nghe lén được, cậu bé cùng Phúc thúc lớn tiếng vạch trần bộ mặt thật của lũ tay sai, khiến Lưu công công tức giận hạ lệnh đánh chết toàn bộ.'),
    ('0:19:00-0:19:50', 'Đúng lúc Tô Tiểu Mãn chuẩn bị chuyển vũ khí qua tủ lạnh để cứu chàng Thái tử, gã trùm đòi nợ Hồ Bưu bất ngờ dẫn đám đàn em bặm trợn ập vào quán, hung hãn đòi đập nát tiệm nếu cô không trả ngay năm trăm vạn tệ, mặc cho cô khóc lóc van xin hắn khất thêm ba ngày.'),
    ('0:19:50-0:20:40', 'Trong khi đó tại lãnh cung Hàn Ngô Viện, Tiêu Cảnh Dực bị đám cấm quân đánh thổ huyết, chúng thô bạo ghì đầu bắt anh phải quỳ xuống nền đá như con chó hoang, nghe Lưu công công cười nhạo dòng máu hoàng gia không bằng loài cầm thú, rồi sai tay chân lấy rượu độc đổ vào họng anh.'),
    ('0:20:50-0:21:40', 'Nghe tiếng kêu cứu tuyệt vọng vọng ra từ chiếc tủ lạnh khi côn đồ đang đập quán, Tô Tiểu Mãn liền liều mạng vớ lấy dao phay kề thẳng vào cổ Hồ Bưu, gằn giọng tuyên bố sẵn sàng đổi một mạng lấy một mạng ngay tại chỗ, khiến gã giang hồ xanh mặt sợ hãi phải ra lệnh rút lui.'),
    ('0:21:45-0:22:35', 'Vừa đuổi được đám côn đồ ra khỏi cửa quán, Tô Tiểu Mãn liền đẩy chiếc hòm gỗ dài, truyền thẳng vũ khí qua luồng sáng kỳ ảo của cánh cửa tủ lạnh trong bếp, giúp Tiêu Cảnh Dực kịp thời đón lấy khẩu súng máy hạng nặng giữa sân viện, rồi xả một loạt đạn gầm vang xuống chân kẻ địch.'),
    ('0:22:15-0:23:32', 'Loạt đạn từ khẩu thần binh hiện đại bắn nát mặt gạch dưới chân đám cấm quân kia, khiến Lưu công công sợ tới mức hồn xiêu phách lạc quỳ mọp xuống xin tha, miệng lắp bắp gọi đó là thần binh thiên lôi do thần tiên ban xuống, rồi bị Tiêu Cảnh Dực ra lệnh trói chặt tống vào nhà củi.'),
    ('0:23:22-0:24:12', 'Dưới họng súng đen ngòm của vị Thái tử trẻ tuổi, Lưu công công run rẩy khai ra toàn bộ, rằng Hoàng hậu cùng Tạ Sùng Uyên đã định sẵn kế hoạch bức tử anh, cài cắm ba nghìn quân Huyền Vũ doanh chờ lệnh vây viện trước Đông Chí, còn ở hiện đại Hồ Bưu lại đánh úp Tô Tiểu Mãn.'),
    ('0:24:15-0:25:05', 'Phát hiện Tô Tiểu Mãn chỉ có một mình trong tiệm nên Hồ Bưu liền kéo sập cửa cuốn, hắn hung hãn bóp cổ lôi cô vào bếp đánh đập tàn nhẫn để trả thù, ép cô gánh khoản nợ năm trăm vạn tệ do bố mẹ để lại, mặc cho cô uất ức bảo hắn đi tìm con trai họ.'),
    ('0:25:05-0:25:55', 'Bỏ ngoài tai lời phân trần của cô chủ nhỏ, Hồ Bưu sai đàn em ghì chặt tay cô, đè bàn tay phải từng cầm dao của Tô Tiểu Mãn lên mặt thớt gỗ, vung gậy sắt định đập gãy từng ngón tay để cô tàn phế suốt đời, đồng thời hăm dọa sẽ đập nát chiếc tủ lạnh trong quán.'),
    ('0:26:35-0:27:25', 'Trong lúc giằng co quyết liệt khiến chiếc vòng ngọc chạm phượng rơi khỏi túi áo cô chủ, Hồ Bưu liền sáng mắt định cướp lấy món cổ vật quý giá để trừ lãi, song cô chủ nhỏ đã liều chết nhào tới giữ chặt kỷ vật của Tiêu Cảnh Dực, trước khi chiếc vòng văng thẳng vào tủ lạnh.'),
    ('0:28:05-0:28:55', 'Nhặt được chiếc vòng ngọc dính máu lăn ra từ bức bình phong sơn thủy nơi lãnh cung, Tiêu Cảnh Dực lập tức hiểu ra ân nhân của mình đang gặp đại nạn, trong khi ở đầu bên kia Hồ Bưu đang dí gậy sắt vào mặt Tô Tiểu Mãn, buông lời cay độc mắng cô là gánh nặng bị vứt bỏ.'),
    ('0:29:15-0:30:05', 'Nỗi đau bị cha mẹ ruột chê là đồ lỗ vốn rồi bỏ lại dưới mưa ùa về, song Tô Tiểu Mãn đã kiên cường ngẩng đầu khẳng định chính cô tự nuôi mình, chứ tuyệt đối không phải gánh nặng ăn bám bất kỳ ai trên đời, ngay trước khi cánh cửa tủ lạnh bật tung trong ánh sáng tím.'),
    ('0:30:05-0:30:55', 'Bước thẳng ra từ tủ lạnh với khẩu súng máy nòng xoay gầm rú dữ dội trên tay, Tiêu Cảnh Dực lạnh lùng tuyên bố kẻ nào dám xúc phạm Tô Tiểu Mãn phải chết, dọa Hồ Bưu cùng đám đàn em sợ vỡ mật tháo chạy khỏi quán, trước khi cô ngăn anh bước quá bán kính mười mét.'),
    ('0:30:55-0:31:45', 'Nhận hai mươi mốt hạt châu và tiền cổ từ Tiêu Cảnh Dực để ghi giấy trừ nợ, Tô Tiểu Mãn vừa tiễn anh vào tủ lạnh thì cô bạn luật sư Đình Đình tới, nhìn thấy cảnh chàng trai cổ trang biến mất liền trố mắt kinh ngạc, song đã bị cô lấp liếm là dịch vụ ẩm thực mới.'),
    ('0:31:55-0:32:45', 'Mang năm mươi đồng Kiến Nguyên Thông Bảo lên sóng giám định với chuyên gia Hạ lão sư, Tô Tiểu Mãn vỡ òa khi mỗi đồng tiền cổ đã tăng lên ba mươi vạn, giúp cô thu về một nghìn ba trăm năm mươi vạn tệ tiền mặt, lập tức gạch nợ của Trương ca và một phần nợ Hồ Bưu.'),
    ('0:32:45-0:33:35', 'Bịa chuyện đang cung cấp đạo cụ cho đoàn phim cổ trang đầu tư hàng trăm triệu, Tô Tiểu Mãn đặt mua của Trương ca một trăm ngỗng quay cùng hai trăm gà nướng, thêm năm mươi thùng rượu trắng và mười bộ sạc năng lượng mặt trời, kèm năm trăm hộp cơm tự sôi chuyển sang lãnh cung.'),
    ('0:33:35-0:34:25', 'Nghe tin Lưu công công thất bại khiến Hoàng hậu nổi trận lôi đình trong Phượng Nghi Cung, Tạ Sùng Uyên liền sai ba nghìn quân Huyền Vũ bao vây chặt Hàn Ngô Viện, quyết không cho một hạt gạo lọt vào hòng bỏ đói Tiêu Cảnh Dực, song Tô Tiểu Mãn đã kịp chuyển sang cả kho đồ ăn sẵn.'),
    ('0:34:35-0:35:25', 'Khi thuộc hạ bẩm báo Phế Thái tử chẳng những không chết đói mà còn mở tiệc thịt rượu, hương thơm ngào ngạt bay ra ngoài tường viện cùng hàng chục vò rượu mạnh, Tạ Sùng Uyên tức điên người liền vào cung tâu với Hoàng hậu kế mới, nhằm lấy mạng toàn bộ người trong viện không tốn binh đao.'),
    ('0:35:25-0:36:15', 'Với âm mưu cắt đứt hoàn toàn mạch nước ngầm để biến Hàn Ngô Viện thành quan tài sắt, Tạ Sùng Uyên nhanh chóng làm cạn giếng nước hòng bức năm mươi sáu người chết khát, khiến lượng nước dự trữ trong sân chẳng cầm cự nổi ba ngày, buộc Tiêu Cảnh Dực phải vội sang cầu cứu Tô Tiểu Mãn.'),
    ('0:36:15-0:37:05', 'Nhận thấy mấy thùng nước khoáng trong tiệm chẳng thấm vào đâu so với năm mươi sáu người, Tô Tiểu Mãn liền gọi điện mượn gấp chiếc xe bồn cứu hỏa của Trương ca, đồng thời đưa trước mấy thùng nước ngọt về lãnh cung giải khát, khiến lão nô Phúc thúc uống thử mà khen là tiên lộ.'),
    ('0:37:15-0:38:05', 'Hay tin Hàn Ngô Viện dù bị cắt nguồn nước song mỗi ngày vẫn nổi lửa nấu cơm, thậm chí người trong viện còn hồng hào khỏe mạnh và vang tiếng cười nói, Tạ Sùng Uyên liền mất hết kiên nhẫn nên mật lệnh cho mười tên tử sĩ, nhân lúc canh ba đổi gác trèo qua núi phóng hỏa.'),
    ('0:38:10-0:39:00', 'Đêm trước ngày Đông Chí biển lửa hung tàn bất ngờ bùng lên bao vây Hàn Ngô Viện, ngọn lửa dữ dội thiêu rụi toàn bộ chăn đệm và bịt kín mọi lối thoát, đẩy năm mươi sáu con người vào cảnh tuyệt vọng giữa vòng vây khói lửa, đúng lúc Tô Tiểu Mãn đọc thấy tin khảo cổ về đại hỏa.'),
    ('0:39:15-0:40:05', 'Bàng hoàng nhận ra kiếp nạn tử vong tuổi hai mươi tám của Tiêu Cảnh Dực là đêm nay, Tô Tiểu Mãn liền truyền thẳng chiếc xe cứu hỏa màu đỏ qua cổng thời không, rồi cô lớn tiếng hướng dẫn anh mở chiếc van đỏ cỡ lớn trên xe, kéo ống nước màu đen trên nóc nhắm vào đám cháy.'),
    ('0:40:05-0:40:55', 'Làm theo lời chỉ dẫn của cô chủ nhỏ, Tiêu Cảnh Dực cùng thiếu niên A Viên vặn van, xả cột nước khổng lồ từ chiếc xe sắt đỏ rực dập tắt biển lửa, cứu sống toàn bộ người trong lãnh cung trước âm mưu của Tạ Sùng Uyên, đồng thời tận dụng nửa bồn nước tích trữ vào chum.'),
    ('0:40:52-0:41:42', 'Nghe tin ba nghìn quân vây khốn cùng trận đại hỏa đều không hại nổi Tiêu Cảnh Dực, Tạ Sùng Uyên liền nghe lời thuộc hạ chuyển sang vu khống Thái tử dùng vu cổ, bởi vu cổ vốn là đại kỵ hoàng gia khiến đối phương khó lòng cãi, còn Tiêu Cảnh Dực cũng sang nhờ Tô Tiểu Mãn tìm người.'),
    ('0:41:45-0:42:35', 'Người mà Tiêu Cảnh Dực cần tìm là Chu Bình, vị tiên sinh sổ sách của Hầu phủ, người duy nhất từng thừa lúc hỗn loạn trốn thoát khỏi Thiên lao ba năm trước, và Tô Tiểu Mãn đã nhanh chóng tra cứu dã sử về vụ cướp xe tù, suy luận ra ông ta đang ẩn náu ở chùa Bạch Mã.'),
    ('0:42:35-0:43:25', 'Không chỉ tìm ra nơi ẩn náu của nhân chứng sống, Tô Tiểu Mãn còn thấy một luận văn, do vị giáo sư sử học uy tín thời hiện đại viết để minh oan cho Hầu phủ, trong đó công nghệ giám định chứng minh bức mật thư năm xưa là giả, hoàn toàn do chính tay Tạ Sùng Uyên ngụy tạo.'),
    ('0:43:25-0:44:15', 'In toàn bộ bản đối chiếu bút tích cùng bản sao mật thư giao cho Tiêu Cảnh Dực, Tô Tiểu Mãn dặn anh phải tự tìm cách đưa nhân chứng Chu Bình vào cung, bởi chỉ khi có đủ nhân chứng lẫn vật chứng thì mới lật được án, đồng thời cô tinh nghịch nhắc anh nhớ trả công bằng vàng.'),
    ('0:44:15-0:45:05', 'Trở về Hàn Ngô Viện và cố tình nhắc lại án cũ của Trấn Bắc Hầu phủ, Tiêu Cảnh Dực mượn hiện tượng sao Huỳnh Hoặc Thủ Tâm nhằm kéo dài ba ngày, song Tạ Sùng Uyên đã lập tức đánh hơi thấy nguy hiểm và ra tay đêm nay, buộc Tiêu Cảnh Dực phải sai Phúc thúc đón Chu Bình.'),
    ('0:45:15-0:46:58', 'Giữa mưa tên rực lửa trong đêm tối, Tiêu Cảnh Dực ẩn mình sau chiếc xe cứu hỏa, dùng súng hiện đại bắn gục từng tên sát thủ áo đen để cầm chân địch, và ngay khi súng hết đạn thì anh liền rút gậy điện chích thẳng vào chúng, tạo thời cơ cho A Viên đưa Chu Bình qua cửa sổ.'),
    ('0:47:00-0:47:50', 'Rơi nước mắt trao cho Tiêu Cảnh Dực cuốn sổ sách đẫm máu cất giấu ba năm, Chu Bình nghẹn ngào kể lại nỗi oan khuất của cả phủ Trấn Bắc Hầu năm xưa, và được vị Thái tử hứa sẽ bắt Tạ Sùng Uyên trả nợ máu, đúng lúc đám thích khách đột ngột rút lui vì Hoàng đế tới.'),
    ('0:48:10-0:49:00', 'Sau khi sai Phúc thúc giấu kín toàn bộ vũ khí hiện đại vào ngăn bí mật, Tiêu Cảnh Dực bình tĩnh quỳ xuống trước Hoàng đế giữa lúc Tạ Sùng Uyên vu khống, lão bảo anh cất giấu yêu vật nên bị trời phạt hòng ngăn vua vào, song anh đã dâng lên sổ sách cùng bản đối chiếu.'),
    ('0:49:00-0:49:50', 'Đứng trước nhân chứng sống Chu Bình cùng bằng chứng vạch trần việc ngụy tạo mật thư, Tạ Sùng Uyên hoảng loạn định đổ vấy cho Phế Thái tử cấu kết yêu nhân, song đã bị Hoàng đế chất vấn thẳng mặt về chuyện làm sao Chu Bình vào cung, rồi nhà vua liền hạ chỉ tống giam lão vào ngục.'),
    ('0:49:55-0:50:45', 'Mùa đông năm Đại Ninh thứ mười bảy, vụ án oan của Trấn Bắc Hầu phủ được xét xử, khiến Tô Tiểu Mãn ở hiện đại đọc dòng sử liệu mới cập nhật mà khóc, còn tại triều đình Hoàng đế cũng truy phong Trấn Bắc Hầu làm Trung Nghĩa Vương, đồng thời khôi phục ngôi vị Thái tử cho anh.'),
    ('0:50:45-0:52:28', 'Nhằm đẩy Tiêu Cảnh Dực vào chỗ vạn kiếp bất phục, Hoàng hậu liền mở tiệc mời Thôi Trạch, gọi thêm mấy vị Thượng thư tới bàn chuyện xe sắt ở Hàn Ngô Viện, mượn cớ sao Huỳnh Hoặc Thủ Tâm chưa lui để ép Khâm Thiên Giám bói lại, đẩy vị Thái tử lên giàn lửa trước bá quan.'),
    ('0:52:30-0:53:20', 'Trong buổi chầu sáng hôm sau tại đại điện, Quốc trượng Thôi Trạch ngang nhiên bước ra chất vấn, lão chỉ rõ xe nước trong quân đội cần người đẩy hoặc ngựa kéo mới chạy, còn chiếc xe của Thái tử tự nổ máy phun nước ắt là yêu vật, rồi ép Hoàng đế tổ chức đại lễ Tế Thiên.'),
    ('0:53:55-0:54:50', 'Sau khi Hoàng đế hạ lệnh ba ngày nữa phải biểu diễn xe thần tại lễ Tế Thiên, lão nô Phúc thúc đã tiết lộ cho Tiêu Cảnh Dực một bí mật chôn giấu, rằng trước khi bị tru di thì Trấn Bắc Hầu từng nhận mật thư của vua, ép ông giao binh quyền rồi mặc nhiên cho gian thần.'),
    ('0:55:00-0:55:50', 'Thấu hiểu rằng phụ hoàng vốn sợ hai mươi vạn binh quyền công cao át chủ của nhà ngoại, và nay chỉ ủng hộ anh lật án để dùng anh kiềm chế họ Thôi, Tiêu Cảnh Dực mang bàn tay rỉ máu vì bị người họ Thôi chặn đường sang quán, nghẹn ngào tâm sự khi không thể lật đổ cha.'),
    ('0:56:40-0:57:35', 'Nghe chàng Thái tử hoang mang trước lễ Tế Thiên, Tô Tiểu Mãn liền truyền cho anh dũng khí, cô khuyên anh trên đời này dựa vào trời đất hay cha mẹ đều không bằng mình, rồi hiến kế dùng khoa học đóng gói mê tín bằng cách sơn vàng xe cứu hỏa, đồng thời khảm vòng ngọc của mẫu hậu lên xe.'),
    ('0:57:50-0:58:40', 'Hẹn với Tô Tiểu Mãn rằng sau khi vượt qua cửa ải này sẽ nói lời đáy lòng, Tiêu Cảnh Dực khoác triều phục bước lên đài Tế Thiên trước mặt bá quan, điềm tĩnh đối diện với lời đe dọa hống hách của Quốc trượng Thôi Trạch, giữa bầu không khí căng thẳng trên quảng trường hoàng cung.'),
    ('0:58:50-0:59:40', 'Kéo tấm lụa đỏ để lộ chiếc xe cứu hỏa sơn vàng khảm vòng ngọc loan phượng, Tiêu Cảnh Dực dõng dạc tuyên bố thần xa theo lửa sấm giáng xuống cứu năm mươi sáu người, hoàn toàn ứng nghiệm với quẻ bói của Phó Giám chính Lý Thủ Chuyết, mặc cho Quốc trượng Thôi Trạch xin đốt hủy.'),
    ('0:59:40-1:00:30', 'Thấy chiếc xe sắt tự nổ máy di chuyển và phun rồng nước không cần người kéo, Thôi Trạch cùng Nhị hoàng tử hốt hoảng quỳ rạp xuống đất kêu gào đó là yêu vật, song Hoàng đế nhìn thấy kỷ vật của thê tử liền bác bỏ tội vu cổ, chỉ hạ lệnh tịch thu xe và giam lỏng anh.'),
    ('1:00:55-1:01:45', 'Bị phụ hoàng tước mất thần xa và hạ lệnh không có chiếu chỉ không được ra ngoài, Tiêu Cảnh Dực đứng dưới ánh nến thấm thía lời dạy tự lực của Tô Tiểu Mãn, thề sẽ tự tay xé nát sự mặc nhiên của vua chứ không khuất phục, đúng lúc có tin Thôi Trạch bày mưu tại bãi săn.'),
    ('1:02:40-1:03:35', 'Biết Thôi Trạch định ép mình biểu diễn lại chiếc xe nước đã bị tịch thu tại hội săn, nhằm khép anh vào tội khi quân trước trăm quan trong buổi đi săn sắp tới, Tiêu Cảnh Dực liền sang tìm Tô Tiểu Mãn nhận đèn pha cùng súng điện, kèm đoạn băng máy tính bảng của Thiên Cung.'),
    ('1:03:40-1:04:30', 'Đúng như dự đoán của cô chủ nhỏ, đêm trước hội săn truyền về mật báo từ cung, rằng nhà họ Thôi đã lén thả mấy con gấu đen hung dữ vào bãi săn núi Tây, dưới sự làm ngơ của Hoàng đế hòng mượn mãnh thú đoạt mạng Thái tử, nên hôm sau Tiêu Cảnh Dực cố tình tới muộn.'),
    ('1:04:35-1:05:25', 'Ngay khi con gấu khổng lồ mắt đỏ ngầu bất ngờ xổng chuồng lao thẳng về ngự giá, giữa tiếng la hét thất thanh của văn võ bá quan đang hoảng loạn bỏ chạy, Tiêu Cảnh Dực liền bật đèn pha chiếu thẳng làm mù mắt thú dữ tại chỗ, rồi rút súng điện chích một đòn khiến nó đổ rạp.'),
    ('1:05:25-1:06:15', 'Giữa lúc Thôi Trạch và Nhị hoàng tử định chụp mũ anh dùng tà thuật hạ gấu dữ, Tiêu Cảnh Dực liền rút máy tính bảng phát đoạn hình ảnh của Tô Tiểu Mãn, trong đó cô tự xưng là Các chủ Thiên Cung Các và chọn anh làm thiên tử, khiến Hoàng đế cùng triều thần ngỡ thần tiên.'),
    ('1:06:15-1:07:05', 'Nhờ công lao hộ giá và uy thế thần tiên che chở tại bãi săn núi Tây hôm ấy, Tiêu Cảnh Dực được vua ban thưởng chuyển sang Thừa Càn Cung cùng năm mươi sáu người, giúp anh thực hiện lời hứa đưa những người trung thành rời Hàn Ngô Viện, không quên sai A Viên khiêng theo bình phong.'),
    ('1:07:02-1:07:50', 'Trong lúc đó ở thế giới hiện đại, Tô Tiểu Mãn gọi thẳng Hồ Bưu tới tiệm tính nợ, cô khấu trừ tiền đã trả cùng mười đồng tiền cổ trị giá ba trăm vạn tệ, rồi ném túi tiền mặt tám trăm vạn trả đứt nợ bảy trăm bốn mươi vạn, đanh thép cảnh cáo hắn không được tới đây.'),
    ('1:07:50-1:08:40', 'Sau khi an trí chăn ấm nệm êm cho mọi người tại Thừa Càn Cung và gọi Triệu Hoành, Tiêu Cảnh Dực bước qua bình phong sang tiệm nhận lô bộ đàm từ Tô Tiểu Mãn, thiết bị liên lạc nội bộ trong phạm vi năm dặm giúp anh nắm tin tức, để chính thức chuyển từ phòng thủ sang tấn công.'),
    ('1:08:45-1:09:35', 'Ngay đêm đầu tiên tại Thừa Càn Cung, mười hai tên thích khách mang lệnh bài họ Thôi, cùng thẻ bài của phủ Nhị hoàng tử lén đột nhập vào cung hòng ám sát anh, song đã bị Tiêu Cảnh Dực dùng bộ đàm chỉ huy vây bắt gọn gàng trong đêm, giữ lại hai tên sống sót để áp giải lên điện.'),
    ('1:09:35-1:10:25', 'Dù Quốc trượng Thôi Trạch cùng Nhị hoàng tử vội chối bay chối biến trước mặt vua, viện cớ lệnh bài gia đinh bị kẻ gian lấy cắp vài hôm trước để vu oan, nhà vua vẫn nhân cơ hội này tước bớt quyền lực và đuổi Thôi Trạch về hưu, trong khi Tô Tiểu Mãn lại tới chỗ Trương ca gom hàng.'),
    ('1:10:35-1:11:25', 'Từ đèn cực tím nghiệm độc và lựu đạn choáng cùng ống nhòm ban đêm theo dõi địch, cho tới máy chiếu thiên tượng ba đoạn giúp thu phục Khâm Thiên Giám lẫn Công Bộ, Tô Tiểu Mãn dốc lòng trang bị tận răng cho Tiêu Cảnh Dực đi đánh trận, khiến anh cảm động hứa ban cho cô vinh hoa.'),
    ('1:11:30-1:12:20', 'Trò chuyện cùng cô bạn luật sư Đình Đình sau khi đã thanh toán sạch mọi khoản nợ, Tô Tiểu Mãn tự hào tuyên bố sẽ biến tiệm ăn thành trạm hậu cần vững chắc, để chàng Thái tử yên tâm bảo vệ giang sơn còn cô đứng sau bảo vệ anh, trong khi Tiêu Cảnh Dực đã rải ám vệ khắp thành.'),
    ('1:12:25-1:13:15', 'Phát hiện mật đạo dưới phủ họ Thôi thông ra ngoài thành, Tiêu Cảnh Dực lập tức vào Thiên lao, anh lạnh lùng vạch trần cho Tạ Sùng Uyên biết chuyện con gái của lão, tháng trước vừa bị Thôi Trạch gả cho Tam vương tử Bắc Địch kèm bản đồ, và sắp bị hạ sát để đổi lấy mật thư.'),
    ('1:13:15-1:14:05', 'Biết Thôi Trạch chỉ coi con gái mình là con tin rẻ mạt để ép mình ngậm miệng, Tạ Sùng Uyên uất hận khai ra kế hoạch tạo phản của họ Thôi ba ngày tới, rằng Hoàng hậu sẽ bỏ độc vào rượu còn Thôi Trạch dẫn quân vào cung, đồng thời tiết lộ Hoàng hậu đã hại Tiên Hoàng hậu.'),
    ('1:14:20-1:15:15', 'Vừa rời Thiên lao đã bị đám sát thủ họ Thôi bắn tên phục kích ngoài cửa triều đình, Tiêu Cảnh Dực liền sang tìm Tô Tiểu Mãn nhận áo giáp chống đạn Thiên Cang Giáp, cô khuyên anh ngày mai mặc lót bên trong triều phục để dụ xạ thủ bắn, giúp ông vua đa nghi thấy sát ý họ Thôi.'),
    ('1:15:40-1:16:30', 'Sáng hôm sau ngay trước thềm kim điện, hàng loạt mũi tên nỏ từ chỗ nấp bắn vào ngực, khiến Tiêu Cảnh Dực ngã gục xuống bậc đá trong tiếng cười của bè lũ họ Thôi, song ngay sau đó anh lại bình thản đứng dậy trước sự kinh hoàng của bá quan, vạch áo bào cho vua xem lớp giáp cắm tên.'),
    ('1:16:45-1:17:35', 'Cảnh cáo phụ hoàng rằng hôm nay họ Thôi dám hại hoàng tử thì mai dám hại vua, Tiêu Cảnh Dực quyết đánh cho Thôi Trạch vĩnh viễn không ngóc đầu lên nổi trên triều, bằng cách mượn máy in Thiên Sao Thần Cơ chạy điện mặt trời của Tô Tiểu Mãn, rồi sai A Viên đột nhập mật đạo họ Thôi.'),
    ('1:17:35-1:18:25', 'Lấy được cuốn sổ ghi chép việc Thôi Trạch chuyển hai mươi vạn lượng bạc cho Bắc Địch, cùng bức mật thư đóng ấn đầu sói của ngoại bang cất giấu trong mật thất, Tiêu Cảnh Dực dùng máy in sao chép ra hàng trăm bản giống hệt bản gốc, rồi sai ám vệ rải khắp phủ đệ các quan.'),
    ('1:18:25-1:19:15', 'Nhận thêm đèn cực tím nghiệm độc cùng máy chiếu di động từ Tô Tiểu Mãn để thu lưới, Tiêu Cảnh Dực biết chỉ dựa vào mấy món đồ này chưa đủ cản năm nghìn quân, nên Tô Tiểu Mãn hứa sẽ truyền thẳng một chiếc chiến xa bọc thép qua bình phong, kèm lời hẹn sau khi thắng sẽ nấu mì.'),
    ('1:19:15-1:20:05', 'Tại yến tiệc hoàng cung đêm hôm đó, ngay khi Hoàng hậu dâng bình rượu quế hoa chúc thọ, Tiêu Cảnh Dực liền bước ra dùng đèn cực tím chiếu ánh sáng xanh vạch trần độc dược, đồng thời bật máy chiếu phơi bày mật thư cấu kết Bắc Địch lên lụa trắng, đúng lúc năm nghìn quân Thôi Trạch tràn vào.'),
    ('1:20:10-1:21:00', 'Giữa lúc Nhị hoàng tử đắc ý cười gằn ép hoàng huynh chịu trói vì tưởng vua trúng độc, Tiêu Cảnh Dực liền hộ tống mọi người lùi ra sau đại điện rồi đón chiến xa, anh nhảy lên buồng lái điều khiển cỗ máy sắt thép đao thương bất nhập lao ra, húc văng hàng rào khiên chắn của phản quân.'),
    ('1:21:10-1:22:00', 'Tung lựu đạn khói mù mịt và phát loa phóng thanh vang khắp cung rằng thiên phạt đã tới, thượng thiên phái chiến xa giáng thế trừng phạt kẻ nghịch thiên làm trái đạo trời, Tiêu Cảnh Dực lái xe bọc thép nghiền nát đội hình của năm nghìn tư binh, phối hợp cùng đội ám vệ bắt sống phản quân.'),
    ('1:22:05-1:22:55', 'Quỳ xuống trước mặt Hoàng đế sau khi dẹp tan cuộc binh biến đẫm máu tại kinh thành, Tiêu Cảnh Dực dõng dạc tuyên bố không cần chém công thần mà chỉ đòi lẽ công đạo, vì oan hồn mẫu hậu cùng năm mươi sáu mạng người vô tội nơi lãnh cung, buộc nhà vua xử trảm Thôi Trạch và đày Nhị hoàng tử.'),
    ('1:23:15-1:24:10', 'Đích thân tới Thiên lao ném ba mươi bảy bức mật thư đầu sói vào mặt Thôi Trạch, Tiêu Cảnh Dực đập tan lời ngụy biện của lão gian thần vẫn đổ lỗi cho yêu thuật, và khi nghe lão điên cuồng cười nhạo cái chết vì bánh quế hoa của mẫu hậu, anh liền bóp cổ lão tuyên bố sẽ tru di.'),
    ('1:24:45-1:25:35', 'Sau khi gửi tặng Tô Tiểu Mãn cả rương vàng bạc châu báu tịch thu từ phủ họ Thôi, Tiêu Cảnh Dực được Hoàng đế triệu lên điện trao ấn Giám quốc cai quản triều chính, bởi nhà vua đã già yếu không còn sức chống đỡ giang sơn sau biến cố, đồng thời ngậm ngùi thừa nhận đã phụ mẹ con anh.'),
    ('1:25:45-1:26:35', 'Chính thức nắm quyền Thái tử Giám quốc xử lý tấu chương lục bộ trong tiếng hô vạn tuế, Tiêu Cảnh Dực lái chiến xa tuần tra khắp phố phường kinh thành để trấn an dân, hứa từ nay bách tính Đại Ninh sẽ không còn chịu cảnh bị ác bá ức hiếp, rồi anh mỉm cười nhận kẹo hồ lô từ em nhỏ.'),
    ('1:26:40-1:27:30', 'Để giúp Tiêu Cảnh Dực kiểm soát tình hình biên cương từ xa mà không cần chạy bộ, Tô Tiểu Mãn đã nhờ những người bạn đam mê vô tuyến tìm mua máy điện báo, kèm theo cuốn sổ mật mã được dịch sẵn toàn bộ sang chữ phồn thể, giúp mạng lưới Đông Cung truyền tin trong chớp mắt.'),
    ('1:27:35-1:28:25', 'Khi A Viên bẩm báo tháng này đã chặn được hai mươi tám bồ câu của Nhị hoàng tử, Tiêu Cảnh Dực lo kẻ địch sẽ sớm nhận ra sự bất thường mà đổi mật ngữ mới, làm vô hiệu hóa toàn bộ mật mã mà Đông Cung vừa dày công giải dịch, song Tô Tiểu Mãn đã kịp gửi sang máy phá sóng.'),
    ('1:29:00-1:29:50', 'Nhờ thiết bị nhiễu sóng khiến bồ câu đưa thư trong bán kính mười dặm rơi vào trạm gác, Tiêu Cảnh Dực nhận được mật điện khẩn từ ám vệ Triệu Hoành đang bị vây khốn, phơi bày việc Nhị hoàng tử đã ký mật ước bán nước với quân Bắc Địch, nhẫn tâm cắt nhượng ba châu để đổi lấy quân.'),
    ('1:30:00-1:30:50', 'Quyết không để vùng đất phên dậu phía Bắc rơi vào tay giặc hay bỏ mặc thuộc hạ, Tiêu Cảnh Dực liền tập hợp ám vệ và lái xe bọc thép tới Tuyết Lang Cốc, vượt qua bão tuyết lạnh giá kịp thời giải cứu Triệu Hoành đang bị thương nặng, rồi đưa người thuộc hạ cùng mật ước về kinh.'),
    ('1:31:05-1:31:55', 'Nhìn bản mật ước in dấu tay máu bán đứng ba châu phương Bắc của đứa con phản nghịch, Hoàng đế tức giận phát lệnh truy nã bất kể sống chết đối với Tiêu Cảnh Diễm, trong khi gã Nhị hoàng tử điên cuồng đã dẫn ba vạn thiết kỵ Bắc Địch lên đường, vượt sông tiến thẳng về kinh thành cướp ngôi.'),
    ('1:32:10-1:33:00', 'Dựa vào bản đồ công sự phòng ngự trên máy tính bảng do Tô Tiểu Mãn truyền sang, Tiêu Cảnh Dực bình tĩnh chỉ huy A Viên dàn trận ba tầng phòng tuyến bên sông, kích hoạt thuốc nổ dưới nước hất tung bè mảng và ném lựu đạn làm mù mắt địch, khiến đội kỵ binh Bắc Địch tan vỡ trên sông.'),
    ('1:33:15-1:34:05', 'Kết hợp cùng chiến xa bọc thép càn quét khiến ba vạn quân Bắc Địch khiếp vía đầu hàng, Tiêu Cảnh Dực vừa thắng trận trở về thì thấy Nhị hoàng tử đã lẻn vào cung, hắn điên cuồng kề thanh kiếm sắc lẻm vào thẳng cổ họng của Hoàng đế trên điện, gào thét ép nhà vua viết chiếu truyền ngôi.'),
    ('1:34:35-1:35:25', 'Buộc phải ném bỏ vũ khí xuống đất và giao đấu tay không để giữ mạng cho vua, Tiêu Cảnh Dực cố tình chịu đựng những nhát kiếm chém vào người của đứa em độc ác, mặc cho hắn đắc ý cười nhạo anh ở lãnh cung ba năm không cầm vững kiếm, để rồi khi hắn sơ hở anh liền rút súng điện.'),
    ('1:35:35-1:36:25', 'Nghe Nhị hoàng tử gào khóc oán hận người cha thiên vị từ nhỏ trước khi bị lôi đi, Hoàng đế thổ huyết nắm chặt bàn tay Tiêu Cảnh Dực trên bậc thềm đại điện, nghẹn ngào nói lời xin lỗi Tiên Hoàng hậu quá cố vì sự nhẫn tâm của mình, đồng thời dặn dò anh hãy làm một vị vua tốt.'),
    ('1:36:55-1:37:45', 'Giữa buổi thiết triều xét xử tội trạng bán nước cầu vinh của kẻ phản nghịch trước bá quan, Tiêu Cảnh Dực đanh thép vạch trần việc cắt nhượng ba châu gồm hai mươi bảy vạn hộ, đã khiến hơn một triệu bách tính vô tội bị quân Bắc Địch tàn sát, rồi anh hạ lệnh xóa tên hắn và ban rượu độc.'),
    ('1:38:35-1:39:25', 'Trở về tiệm ăn hiện đại với tâm trạng nặng nề sau khi ban rượu độc cho đệ đệ, Tiêu Cảnh Dực được Tô Tiểu Mãn nấu bát mì nóng hổi thêm hai quả trứng gà, cô dịu dàng an ủi rằng mình giúp anh không phải vì tiền cổ hay ngôi Thái tử, mà vì cảm phục tấm lòng thương dân của anh.'),
    ('1:40:50-1:41:40', 'Sau khi lên phương án cứu tế ba châu phương Bắc và tặng Tô Tiểu Mãn trâm phượng, Tiêu Cảnh Dực mang bộ máy đo nhịp tim hiện đại vào cung khám cho phụ hoàng, giúp nhà vua yên tâm đó là y thuật của Thiên Cung Các chứ không phải yêu vật, và anh đã rơi lệ khi cha nhận lỗi.'),
    ('1:43:35-1:44:25', 'Phát hiện gã đạo sĩ Huyền Thanh chân nhân mới tới kinh thành ba tháng trước khả nghi, lại đang dâng thứ tiên đan trường thọ có hàm lượng thủy ngân vượt ba mươi lần, Tiêu Cảnh Dực liền dùng đèn cực tím nghiệm độc ngay trên kim điện trước bá quan, vạch mặt kẻ giả danh đạo sĩ là tàn dư họ Thôi.'),
    ('1:45:15-1:46:05', 'Dù ban ngày bị phụ hoàng nổi giận đuổi ra ngoài vì sợ phải đối mặt cái chết, đêm đó Tiêu Cảnh Dực vẫn đích thân bưng bát thuốc đắng vào giường cho cha mình, trầm giọng nói lời buông bỏ hận thù trong lòng vì không muốn tự làm khổ mình, giúp vị Hoàng đế già thanh thản nhắm mắt xuôi tay.'),
    ('1:47:10-1:48:00', 'Chính thức đăng cơ lên ngôi Hoàng đế và cải nguyên thành Thiên Hựu nguyên niên trước muôn dân, Tiêu Cảnh Dực tuyên bố không cầu vạn tuế mà chỉ cầu không thẹn với dân, rồi nhà vua cho đoàn chiến xa bọc thép mở cổng thành tuần hành trên phố, giữa tiếng reo hò vang dậy khắp kinh thành.'),
    ('1:48:45-1:49:35', 'Giữa lúc tân hoàng vừa ổn định triều cương thì cánh cổng thời không trong tủ lạnh suy yếu, Tô Tiểu Mãn vội dồn sức truyền sang lô vật tư cuối cùng cho Hoàng đế trẻ, từ thuốc kháng sinh và sách nông nghiệp cho tới chiếc mũ phượng tân nương, rồi cô nghẹn ngào bắt anh hứa phải tới tìm cô.'),
    ('1:50:10-1:51:00', 'Bức bình phong sơn thủy tại hoàng cung vụt tắt ánh sáng cùng lúc chiếc tủ lạnh đóng lại, bỏ lại Tiêu Cảnh Dực tuyệt vọng gọi tên người thương giữa đêm vắng nơi cung điện, còn Tô Tiểu Mãn vốn kiên cường chưa từng rơi lệ trước nợ năm trăm vạn, nay lại bật khóc nức nở trong vòng tay Đình Đình.'),
    ('1:52:10-1:53:00', 'Được Đình Đình khích lệ phải tìm cách đòi lại bữa mì gói mà đối phương nợ mình, Tô Tiểu Mãn thức trắng nhiều đêm tìm tới tiệm đồ cổ của chuyên gia Hạ lão sư, qua đó biết được tổ tiên ông là Giám chính Lý Thủ Chuyết của triều Đại Ninh, người từng ghi lại bí pháp dùng gương mở cổng.'),
    ('1:53:35-1:54:25', 'Biết hiện tượng Cửu Tinh Liên Châu mười năm có một sẽ xuất hiện vào rạng sáng Đông Chí, Hoàng đế Tiêu Cảnh Dực bất chấp hiểm nguy huy động tam bộ xây đài Tiếp Dẫn, cho đúc ba vạn sáu nghìn cân đồng nguyên chất thành ba nghìn sáu trăm mặt gương, quyết tâm đánh cược tất cả để đón Hoàng hậu.'),
    ('1:55:40-1:56:35', 'Dùng đồng tiền cổ Kiến Nguyên Thông Bảo và chiếc vòng ngọc chạm phượng làm mỏ neo từ trường, đúng giờ Mão ngày Đông Chí khi chín ngôi sao thẳng hàng rực sáng trên trời, Tiêu Cảnh Dực bước lên đài gương đón luồng sáng thiên tượng nối hai thế giới, rồi anh lao ra từ tủ lạnh ôm chặt Tô Tiểu Mãn.'),
    ('1:58:25-1:59:15', 'Khoác lên mình bộ trang phục hiện đại trẻ trung để theo chân cô chủ nhỏ dạo phố, Tiêu Cảnh Dực thích thú ngắm nhìn đèn điện cùng xe hơi và mua mười gói que cay, rồi cả hai cùng thưởng thức nồi lẩu uyên ương Trùng Khánh kèm nước ngọt, trước khi vị Hoàng đế trẻ đeo tạp dề thái thịt.'),
    ('2:01:45-2:02:35', 'Trong lúc đôi trẻ đang ngọt ngào thưởng thức trà sữa trân châu sau buổi làm việc tại quán, chuyên gia Hạ lão sư bất ngờ mang cuốn cổ thư đã phục chế tới báo tin, rằng dòng chú thích cổ khẳng định cổng thời không có thể đi lại hai chiều, miễn là hai người mang theo vật dẫn và tín tiêu.'),
    ('2:03:45-2:04:35', 'Sau khi ký hợp đồng ủy thác tiệm ăn cho cô bạn thân Đình Đình thay mặt quản lý, Tô Tiểu Mãn nắm chặt tay người thương bước qua đài Tiếp Dẫn về triều Đại Ninh, nơi Tiêu Cảnh Dực long trọng tuyên bố trước bá quan sắc phong cô làm Hoàng hậu, khép lại nỗi cô độc để trọn đời hưởng thái bình.'),
]
